import { defineConfig } from "@hey-api/openapi-ts";

// The committed specification, never a running server. The client is
// gitignored and regenerated by every script that needs it (lint, test,
// build), so it is always the spec's; `task openapi:check` holds the spec
// equal to the handlers.
export default defineConfig({
  input: "../docs/api/openapi.json",
  output: { path: "src/api/generated", postProcess: [] },
  plugins: [
    {
      name: "@hey-api/client-axios",
      runtimeConfigPath: "./src/api/runtime.ts",
    },
    { name: "@hey-api/sdk" },
    { name: "@hey-api/typescript", enums: "javascript" },
  ],
});
